     1	// Package config parses and edits Git configuration files while preserving
     2	// their original formatting.
     3	//
     4	// The go-git raw config decoder/encoder pair round-trips through a canonical
     5	// representation: it drops every comment and cannot represent an empty
     6	// subsection name ("[user \"\"]" is folded into "[user]"). Both are lossy in
     7	// ways that silently corrupt a user's file, so config file mutation here is
     8	// done by splicing bytes in the original document instead.
     9	package config
    10	
    11	import "strings"
    12	
    13	// Key is a parsed configuration key such as "remote.origin.url".
    14	//
    15	// Every field holds the spelling it was given, because git writes a variable
    16	// using the spelling from the command line rather than folding it. Matching,
    17	// by contrast, ignores case for section and variable names, so compare keys
    18	// with Matches and never with ==.
    19	type Key struct {
    20		// Section is the section name as spelled. Section names match
    21		// case-insensitively in Git.
    22		Section string
    23		// Subsection is the subsection name. Subsection names match
    24		// case-sensitively in Git.
    25		Subsection string
    26		// HasSubsection distinguishes "user..name", which addresses the empty
    27		// subsection [user ""], from "user.name", which addresses [user].
    28		HasSubsection bool
    29		// Name is the variable name as spelled. Variable names match
    30		// case-insensitively in Git.
    31		Name string
    32	}
    33	
    34	// KeyNoSectionError reports a key with no '.' separator, matching git's
    35	// "key does not contain a section" diagnostic.
    36	type KeyNoSectionError struct{ Key string }
    37	
    38	func (e *KeyNoSectionError) Error() string {
    39		return "key does not contain a section: " + e.Key
    40	}
    41	
    42	// KeyNoVariableError reports a key that ends at the section separator, matching
    43	// git's "key does not contain variable name" diagnostic.
    44	type KeyNoVariableError struct{ Key string }
    45	
    46	func (e *KeyNoVariableError) Error() string {
    47		return "key does not contain variable name: " + e.Key
    48	}
    49	
    50	// KeyInvalidError reports a key whose section or variable name uses characters
    51	// Git does not accept.
    52	type KeyInvalidError struct{ Key string }
    53	
    54	func (e *KeyInvalidError) Error() string {
    55		return "invalid key: " + e.Key
    56	}
    57	
    58	// ParseKey splits a fully qualified configuration key.
    59	//
    60	// Git splits at the first and the last '.': everything between them is the
    61	// subsection, which may itself contain dots ("remote.team.one.url" addresses
    62	// [remote "team.one"] url). A key with exactly two components has no
    63	// subsection; "a..b" has an empty one.
    64	func ParseKey(key string) (Key, error) {
    65		first := strings.IndexByte(key, '.')
    66		if first < 0 {
    67			return Key{}, &KeyNoSectionError{Key: key}
    68		}
    69	
    70		last := strings.LastIndexByte(key, '.')
    71		if last == len(key)-1 {
    72			return Key{}, &KeyNoVariableError{Key: key}
    73		}
    74	
    75		k := Key{
    76			Section: key[:first],
    77			Name:    key[last+1:],
    78		}
    79	
    80		if first != last {
    81			k.Subsection = key[first+1 : last]
    82			k.HasSubsection = true
    83	
    84			if !validSubsectionName(k.Subsection) {
    85				return Key{}, &KeyInvalidError{Key: key}
    86			}
    87		}
    88	
    89		if !validSectionName(k.Section) || !validVariableName(k.Name) {
    90			return Key{}, &KeyInvalidError{Key: key}
    91		}
    92	
    93		return k, nil
    94	}
    95	
    96	// String renders the key in the form ParseKey accepts.
    97	func (k Key) String() string {
    98		if k.HasSubsection {
    99			return k.Section + "." + k.Subsection + "." + k.Name
   100		}
   101	
   102		return k.Section + "." + k.Name
   103	}
   104	
   105	// Matches reports whether k addresses the same variable as other. Section and
   106	// variable names compare case-insensitively; subsection names compare
   107	// byte-for-byte, and an empty subsection is distinct from none at all.
   108	func (k Key) Matches(other Key) bool {
   109		return k.sameSection(other) && strings.EqualFold(k.Name, other.Name)
   110	}
   111	
   112	// sameSection reports whether both keys address the same section header.
   113	func (k Key) sameSection(other Key) bool {
   114		return strings.EqualFold(k.Section, other.Section) &&
   115			k.HasSubsection == other.HasSubsection &&
   116			k.Subsection == other.Subsection
   117	}
   118	
   119	// validSectionName accepts alphanumerics and '-'. Unlike variable names, a
   120	// section name may start with a digit.
   121	func validSectionName(s string) bool {
   122		if s == "" {
   123			return false
   124		}
   125	
   126		for i := range len(s) {
   127			if !isAlnum(s[i]) && s[i] != '-' {
   128				return false
   129			}
   130		}
   131	
   132		return true
   133	}
   134	
   135	// validVariableName accepts alphanumerics and '-', and requires an alphabetic
   136	// first character.
   137	func validVariableName(s string) bool {
   138		if s == "" || !isAlpha(s[0]) {
   139			return false
   140		}
   141	
   142		for i := range len(s) {
   143			if !isAlnum(s[i]) && s[i] != '-' {
   144				return false
   145			}
   146		}
   147	
   148		return true
   149	}
   150	
   151	func validSubsectionName(s string) bool {
   152		return !strings.ContainsAny(s, "\x00\n")
   153	}
   154	
   155	func isAlpha(c byte) bool {
   156		return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z')
   157	}
   158	
   159	func isAlnum(c byte) bool {
   160		return isAlpha(c) || (c >= '0' && c <= '9')
   161	}

