    13	// Key is a parsed configuration key such as "remote.origin.url".
    14	//
    15	// Every field holds the spelling it was given, because git writes a variable
    16	// using the spelling from the command line rather than folding it. Matching,
    17	// by contrast, ignores case for section and variable names, so compare keys
    18	// with Matches and never with ==.
    19	type Key struct {
    20		// Section is the section name as spelled. Section names match
    21		// case-insensitively in Git.
    22		Section string
    23		// Subsection is the subsection name. Subsection names match
    24		// case-sensitively in Git.
    25		Subsection string
    26		// HasSubsection distinguishes "user..name", which addresses the empty
    27		// subsection [user ""], from "user.name", which addresses [user].
    28		HasSubsection bool
