    35	// "key does not contain a section" diagnostic.
    36	type KeyNoSectionError struct{ Key string }
    37	
    38	func (e *KeyNoSectionError) Error() string {
    39		return "key does not contain a section: " + e.Key
    40	}
    41	
    42	// KeyNoVariableError reports a key that ends at the section separator, matching
    43	// git's "key does not contain variable name" diagnostic.
    44	type KeyNoVariableError struct{ Key string }
    45	
    46	func (e *KeyNoVariableError) Error() string {
    47		return "key does not contain variable name: " + e.Key
    48	}
    49	
    50	// KeyInvalidError reports a key whose section or variable name uses characters
    51	// Git does not accept.
    52	type KeyInvalidError struct{ Key string }
    53	
    54	func (e *KeyInvalidError) Error() string {
    55		return "invalid key: " + e.Key
    56	}
    57	
    58	// ParseKey splits a fully qualified configuration key.
    59	//
    60	// Git splits at the first and the last '.': everything between them is the
    61	// subsection, which may itself contain dots ("remote.team.one.url" addresses
    62	// [remote "team.one"] url). A key with exactly two components has no
    63	// subsection; "a..b" has an empty one.
    64	func ParseKey(key string) (Key, error) {
    65		first := strings.IndexByte(key, '.')
    66		if first < 0 {
    67			return Key{}, &KeyNoSectionError{Key: key}
    68		}
    69	
    70		last := strings.LastIndexByte(key, '.')
    71		if last == len(key)-1 {
    72			return Key{}, &KeyNoVariableError{Key: key}
    73		}
    74	
    75		k := Key{
    76			Section: key[:first],
    77			Name:    key[last+1:],
    78		}
    79	
    80		if first != last {
    81			k.Subsection = key[first+1 : last]
    82			k.HasSubsection = true
    83	
    84			if !validSubsectionName(k.Subsection) {
